            {"name": "guard_no_death_tower_survives",
             "expect_death": False,
             "units": [
                 u("t0", "tower", "blue", 300.0, 300.0, arena=False),
                 u("t1", "tower", "red", VT, 300.0, hp=900.0)],
             "attack": {"kind": "tower_bullet", "by": "t0", "target": "t1"},
             "steps": [{"frames": 1}, {"frames": 1}, {"frames": 3}]},
